entries[375935] = { ["name"] = "Abgefüllte Pheromone", ["text"] = "Wirken in 1.5 sek. 5 min Abklingzeit\nÖffnet eine Flasche voller Pheromone und lockt alle nicht anderweitig beschäftigten, häutbaren Bestien und Drachkin innerhalb von 60 Metern zu Euch.\n\nKann nur im Freien auf den Dracheninseln verwendet werden." }
entries[375936] = { ["name"] = "Sepsis", ["text"] = "25 Energie Nahkampfreichweite\nSofort 1.5 min Abklingzeit\nBenötigt Nahkampfwaffe\nInfiziert das Blut des Ziels und fügt ihm so im Verlauf von 10 Sek. (162.89% der Angriffskraft) Naturschaden zu. Wenn das Ziel die gesamte Effektdauer überlebt, erleidet es zusätzlich (77.5667% der Angriffskraft) Schaden und Ihr erhaltet 1 Einsatz einer Verstohlenheitsfähigkeit für 5 Sek.\n\nWenn 'Sepsis' nicht für die gesamte Effektdauer anhält, wird die Abklingzeit um 30 Sek. verringert.\n\nGewährt 1 Combopunkt." }
entries[375937] = { ["name"] = "Reißender Stoß", ["text"] = "30 Meter Reichweite\nWirken in 1.5 sek.\nBalakar fügt seinem aktuellen Ziel 16981813 körperlichen Schaden zu und lässt es bluten, wodurch es 10 Sek. lang alle 1 Sek. 1454277 körperlichen Schaden erleidet.\n\nErhöht den durch ' Wilder Hieb ' erlittenen Schaden um 500%." }
