entries[376492] = { ["name"] = "Kapuze der dringlichen Zeit", ["text"] = "Wirken in 5 sek. 3\nReagenzien:\nLuftige Seele , Chronostoffballen (4), Temporaler Zauberfaden , Funke (#247)\nOptionale Reagenzien:\nZone:\nAkademie von Algeth'ar und Uldaman: Vermächtnis von Tyr\nMuster:\nErhältlich im Auktionshaus\n\nKapuze der dringlichen Zeit\nWird beim Aufheben gebunden\nKopf Stoff\n164 Rüstung\n+257 Intelligenz\n+416 Ausdauer\nErhöht Eure Tempowertung um + 243.\n+ 236 Vielseitigkeit\nHaltbarkeit 100 / 100\nAnlegen: Wenn Ihr einem neuen Gegner Schaden zufügt, wird Euer Tempo für 10 Sek. um 119 erhöht. Bis zu 5-mal stapelbar.\n70" }
entries[376493] = { ["name"] = "Amicia des Blauen", ["text"] = "Wirken in 5 sek. 3\nReagenzien:\nFrostige Seele , Azurgewobener Ballen (3), Gefrorener Zauberfaden , Funke (#247)\nOptionale Reagenzien:\nZone:\nAkademie von Algeth'ar und Azurblaues Gewölbe\nMuster:\nErhältlich im Auktionshaus\n\nAmicia des Blauen\nWird beim Aufheben gebunden\nSchulter Stoff\n150 Rüstung\n+193 Intelligenz\n+312 Ausdauer\nErhöht Eure kritische Trefferwertung um + 149.\nErhöht Eure Meisterschaftswertung um + 210.\nHaltbarkeit 100 / 100\nAnlegen: Eure Schaden verursachenden Zauber und Fähigkeiten haben eine Chance, an der Position des Ziels eine Explosion arkaner Energie auszulösen, die 5744 Arkanschaden verursacht, der auf Gegner in der Nähe aufgeteilt wird.\n\nDer Schaden erhöht sich pro getroffenem Gegner, bis zu 5 Gegner.\n70" }
entries[376494] = { ["name"] = "Wutentbrannte Bindung der Gestik", ["text"] = "Wirken in 5 sek. 3\nReagenzien:\nWeitschreitersehne (2), Wutentbrannter Wildstoffballen (16), Azurgewobener Ballen , Schillernder Zauberfaden , Funke (#247)\nOptionale Reagenzien:\nVerkäufer:\nEraneth\nZone:\nValdrakken\nKosten:\n3\n\nWutentbrannte Bindung der Gestik\nWird beim Aufheben gebunden\nTaille Stoff\n123 Rüstung\n+193 Intelligenz\n+312 Ausdauer\n+ 231 Vielseitigkeit\nErhöht Eure Meisterschaftswertung um + 128.\nHaltbarkeit 55 / 55\nAnlegen: Wenn Ihr einen Gegner erfolgreich mit einem Kontrollverlusteffekt belegt, ihn unterbrecht oder einen Effekt von einem Ziel bannt, wird Euer Primärwert 10 Sek. lang um 200 erhöht. Kann nur einmal alle 30 Sek. auftreten.\n70" }
entries[376495] = { ["name"] = "Wutentbrannte Beinwickel der Wahrscheinlichkeit", ["text"] = "Wirken in 5 sek. 3\nReagenzien:\nWutentbrannter Wildstoffballen (20), Chronostoffballen , Schillernder Zauberfaden , Funke (#247)\nOptionale Reagenzien:\nVerkäufer:\nEraneth\nZone:\nValdrakken\nKosten:\n3\n\nWutentbrannte Beinwickel der Wahrscheinlichkeit\nWird beim Aufheben gebunden\nBeine Stoff\n191 Rüstung\n+257 Intelligenz\n+416 Ausdauer\nErhöht Eure Tempowertung um + 143.\n+ 335 Vielseitigkeit\nHaltbarkeit 120 / 120\nAnlegen: Nachdem Ihr Euch von einem Kontrollverlusteffekt erholt habt, tun sich Euch neue Möglichkeiten auf, was Euer Tempo 10 Sek. lang um 395 erhöht. Dieser Effekt kann nur einmal alle 30 Sek. auftreten.\n70" }
