entries[376563] = { ["name"] = "Mit Drakoniumstoffschere spielen", ["text"] = "Wirken in 5 sek.\nReagenzien:\nFedergetriebene Drakoniumstoffschere , Drakoniumnadelsatz\nDa Ihr Euer Handwerk gemeistert habt, stimuliert es vielleicht Euren Geist, wenn Ihr an Eurem Werkzeug herumtüftelt? Die einzige Garantie, die es dabei gibt, ist allerdings seine Zerstörung.\nBeruf:\nSchneiderei (100)" }
