entries[376566] = { ["name"] = "Tristes Sargtuch", ["text"] = "Wirken in 2 sek.\nReagenzien:\nErweckter Verfall (5), Wildfadenspule (4), Schillernder Wildstoffballen (12)\nOptionale Reagenzien:\nStickereifaden (#181)\nBeute von:\nVerfallene Weltkreaturen\nMuster:\nErhältlich im Auktionshaus\n\nTristes Sargtuch\nSpielzeug\nBenutzen: Bedeckt kürzlich Verstorbene mit einem Trauertuch. (10 Min Abklingzeit)\n\"Ein kleines Zeichen des Respekts für die kürzlich Verstorbenen.\"" }
entries[376567] = { ["name"] = "Zeitreisekissen", ["text"] = "Wirken in 2 sek.\nReagenzien:\nGeschwungene Vogelfeder (25), Schillernde Feder (5), Wildfadenspule (5), Chronostoffballen\nOptionale Reagenzien:\nStickereifaden (#181)\nVerkäufer:\nDothenos\nZone:\nValdrakken\nValdrakkenabkommen - Ruhmstufe 28\nKosten:\n500\n\nVerkäufer:\nUnatos\nZone:\nValdrakken\nValdrakkenabkommen - Ruhmstufe 28\nKosten:\n500\n\nZeitreisekissen\nSpielzeug\nBenutzen: Platziert ein Zeitreisekissen, das als Sitzgelegenheit dienen kann und sich 5 Min. lang durch die Zeit bewegt. (6 Std. Abklingzeit)\n\"Es geht nur nach vorn. Langsam.\"" }
entries[376568] = { ["name"] = "Kaltes Kissen", ["text"] = "Wirken in 2 sek.\nReagenzien:\nGeschwungene Vogelfeder (25), Schillernde Feder (5), Wildfadenspule (5), Azurgewobener Ballen\nOptionale Reagenzien:\nStickereifaden (#181)\nVerkäufer:\nBoss MagorZone:\nKüste des Erwachens Drachenschuppenexpedition - Ruhmstufe 17Kosten:\n750\nVerkäufer:\nKatalogisiererin JakesZone:\nKüste des Erwachens Drachenschuppenexpedition - Ruhmstufe 17Kosten:\n750\n\nKaltes Kissen\nSpielzeug\nBenutzen: Platziert ein kühlendes Kissen für den Fall, dass es auf den Hosenboden gab. (6 Std. Abklingzeit)\n\"Wird verwendet, nachdem es auf den Hosenboden gab.\"" }
entries[376569] = { ["name"] = "Marktzelt", ["text"] = "Wirken in 2 sek.\nReagenzien:\nWildfadenspule (20), Wildstoffballen (50)\nOptionale Reagenzien:\nStickereifaden (#181)\nSpezialisierung:\nGewandungsherstellung - Oberbekleidung (25)\n\nMarktzelt\nSpielzeug\nBenutzen: Baut ein Marktzelt auf, in dem Ihr einkaufen und Euch entspannen könnt. (2 Min Abklingzeit)\n\"Eröffnet ein Geschäft, um Eure Waren anzubieten, oder entspannt Euch unter der Markise.\"" }
