entries[376880] = { ["name"] = "Gelber Späherottuk", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Gelbe Späherottuks lieben es, sich zu verstecken und mit ihrer Umgebung zu verschmelzen. Wenn sie nicht gerade Verstecken mit ihren Reitern \"spielen\", sind sie die perfekten Begleiter beim Ausspähen feindlicher Lager.\"\nTuskarr von Iskaara\nRuhmstufe:\n25\nVerkäufer:\nTatto\nOrt:\nIskaara\nKosten:\n2\n2\n750" }
