entries[376910] = { ["name"] = "Brauner Kriegsottuk", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Die Tuskarr von Iskaara verabscheuen den Krieg, doch viele der Tuskarr und ihrer Verbündeten haben dennoch mit einem Kriegsottuk an ihrer Seite den Speer ergriffen.\"\nTuskarr von Iskaara\nRuhmstufe:\n30\nVerkäufer:\nTatto\nOrt:\nIskaara\nKosten:\n5\n5\n1.000" }
entries[376912] = { ["name"] = "Otterweltlicher Trägerottuk", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Manche Ottuks sind mehr in Stimmung als andere, Leute herumzutragen.\"\nErfolg:\nDanke fürs Tragen!\nKategorie:\nReittiere" }
entries[376913] = { ["name"] = "Gelber Kriegsottuk", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Die gelben Ottuks des Azurblauen Gebirges sind schlank, listig und klug. Jene, die für den Krieg ausgebildet wurden, sind die edelsten Kavalleriereittiere der Tuskarr und zu Land und zu Wasser gleichermaßen tauglich.\"\nTuskarr von Iskaara\nRuhmstufe:\n30\nVerkäufer:\nTatto\nOrt:\nIskaara\nKosten:\n5\n5\n1.000" }
